// La dirección del CRM y el correo de la gerente, de la tabla configuracion
const config = Object.fromEntries($input.all().map((i) => [i.json.clave, i.json.valor]));
if (!config.crm_url) throw new Error('Falta la fila crm_url en la tabla configuracion');
return [{ json: { crm_url: config.crm_url.replace(/\/$/, ''), correo_gerente: config.correo_gerente ?? '' } }];

// Revisa lo que contestó el CRM. Las alarmas suenan una vez (no cada minuto): n8n guarda en la
// memoria del flujo qué ya avisó. Esa memoria solo existe cuando el flujo corre activo, no a mano.
const memoria = $getWorkflowStaticData('global');
const r = $input.first().json;
const { crm_url, correo_gerente } = $('Preparar').first().json;
const ahora = Date.now();
const MEDIA_HORA = 30 * 60 * 1000;
const alarmas = [];

// n8n reescribe los mensajes con códigos de red (ECONNREFUSED...): se traducen antes
const traducir = (m) =>
  /ECONNREFUSED|ECONNRESET/.test(m) ? 'el CRM no contesta: está apagado o sin conexión'
  : /ETIMEDOUT|ESOCKETTIMEDOUT|timeout/i.test(m) ? 'el CRM tardó demasiado en contestar'
  : /ENOTFOUND|EAI_AGAIN/.test(m) ? 'no se encontró la dirección del CRM'
  : /401|authoriz/i.test(m) ? 'la llave no coincide (AUTOMATIZACIONES_TOKEN en n8n y en el CRM)'
  : m;

if (r.error || !Array.isArray(r.pendientes)) {
  // El CRM no contestó bien: alarma la primera vez y después cada media hora mientras dure
  memoria.caidoDesde ??= ahora;
  if (!memoria.ultimaAlarmaCaida || ahora - memoria.ultimaAlarmaCaida >= MEDIA_HORA) {
    memoria.ultimaAlarmaCaida = ahora;
    const minutos = Math.round((ahora - memoria.caidoDesde) / 60000);
    const desde = minutos ? ` (desde hace ${minutos} minutos)` : '';
    const motivo = traducir(r.error?.message ?? String(r.error ?? 'respuesta inesperada'));
    alarmas.push(`No se pudo revisar el buzón del CRM${desde}: ${motivo}. Mientras tanto, los leads del formulario quedan en el CRM pero no reciben avisos.`);
  }
  return [{ json: { alarma: alarmas.join(' ') || null, leads: [] } }];
}
delete memoria.caidoDesde;
delete memoria.ultimaAlarmaCaida;

// Avisos sin confirmar (n8n se detuvo, o falló la confirmación): una alarma por lead. No se reenvían
// solos: a veces los correos sí salieron y solo falló la confirmación
memoria.atascadosAvisados ??= [];
const atascados = (r.atascados ?? []).filter((x) => !memoria.atascadosAvisados.includes(x.clave));
if (atascados.length) {
  memoria.atascadosAvisados = [...memoria.atascadosAvisados, ...atascados.map((x) => x.clave)].slice(-200);
  const detalle = atascados.map((x) => `${x.clave} (ejecución ${x.ejecucion} de 01c)`).join(', ');
  alarmas.push(`Los avisos de ${atascados.length} lead(s) no quedaron confirmados: ${detalle}. Revisa esa ejecución en n8n antes de reenviar: puede que los correos sí hayan salido.`);
}

// Sin la llave de las huellas, el formulario responde "intenta más tarde" a todos
if (r.formulario && r.formulario.huella_configurada === false) {
  if (!memoria.ultimaAlarmaHuella || ahora - memoria.ultimaAlarmaHuella >= MEDIA_HORA) {
    memoria.ultimaAlarmaHuella = ahora;
    alarmas.push('Falta HUELLA_SECRETA en el servidor del CRM: el formulario /cotiza responde "intenta más tarde" a todos.');
  }
}

// Los topes del formulario: una alarma por hora o por día
const f = r.formulario ?? {};
const hora = new Date().toISOString().slice(0, 13);
const dia = hora.slice(0, 10);
if (f.ultima_hora >= f.tope_hora && memoria.topeHora !== hora) {
  memoria.topeHora = hora;
  alarmas.push(`El formulario llegó al tope de ${f.tope_hora} envíos en una hora: los visitantes ven "intenta más tarde". ¿Un ataque?`);
}
if (f.ultimo_dia >= f.tope_dia && memoria.topeDia !== dia) {
  memoria.topeDia = dia;
  alarmas.push(`El formulario llegó al tope de ${f.tope_dia} envíos en 24 horas: los visitantes ven "intenta más tarde". ¿Un ataque?`);
}

// Lo que necesita 01c por cada lead
const leads = r.pendientes.map((p) => ({
  respuesta: p.respuesta,
  cuerpo: { ...(p.cuerpo ?? {}), clave: p.clave },
  correo_gerente,
  crm_url,
}));
return [{ json: { alarma: alarmas.length ? alarmas.join(' ') : null, leads } }];

// Todas las alarmas de esta vuelta en un solo aviso, después de mandar los avisos de los leads
const alarmas = [];
const revision = $('Revisar la respuesta').first().json.alarma;
if (revision) alarmas.push(revision);
if ($('Avisos del lead (01c)').isExecuted) {
  const fallidos = $('Avisos del lead (01c)').all().filter((i) => i.json.error);
  if (fallidos.length) {
    alarmas.push(`Fallaron los avisos de ${fallidos.length} lead(s): ${fallidos.map((i) => i.json.error?.message ?? i.json.error).join(' | ').slice(0, 300)}. Revisa las ejecuciones de 01c.`);
  }
}
return [{ json: { alarma: alarmas.length ? alarmas.join(' ') : null } }];
